#!/usr/bin/env bash
# shellcheck disable=SC1087,SC2329,SC1091,SC2015
# (SC1087 and SC2329 come from the unmodified wizard library below.)
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: tethys setup. Run as the agent user (corvus) on tethys, not on vidar.
# ──────────────────────────────────────────────────────────────────────────
#
# Usage: deploy/agent-host/setup-tethys.sh [--dry-run]
#   --dry-run  checks only: prints what each stage would do, changes nothing,
#              asks nothing.
#
# Every stage checks first and skips what is already done, so reruns are safe.
# Overridable by env: AGENT_USER (corvus), GH_USER (Brijunas), GH_REPO
# (Brijunas/watt-wise), OP_VAULT ("Watt Wise Development"), WW_CONFIG_DIR
# (~/.config/wattwise).

DRY_RUN=0
AGENT_USER="${AGENT_USER:-corvus}"
GH_USER="${GH_USER:-Brijunas}"
GH_REPO="${GH_REPO:-Brijunas/watt-wise}"
OP_VAULT="${OP_VAULT:-Watt Wise Development}"
WW_CONFIG_DIR="${WW_CONFIG_DIR:-$HOME/.config/wattwise}"
OP_TOKEN_FILE="$WW_CONFIG_DIR/op-token"
DOCKER_REPO_URL="https://download.docker.com/linux/fedora/docker-ce.repo"

# Packages from the Fedora repositories.
TOOL_PACKAGES=(tmux jq ShellCheck unison git gh curl)
# Chromium's runtime libraries for Playwright. `playwright install-deps` only
# knows apt, so the Fedora names are listed here.
PLAYWRIGHT_PACKAGES=(nss nspr atk at-spi2-atk cups-libs libdrm libxkbcommon
  libXcomposite libXdamage libXfixes libXrandr mesa-libgbm alsa-lib pango cairo
  at-spi2-core libX11 libXext libxcb)

# run CMD... prints the command and runs it, or only prints it in a dry run.
run() {
  if (( DRY_RUN )); then note "dry-run: $*"; return 0; fi
  "$@"
}

# ok / bad print a verification result. bad returns failure so callers can chain.
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
bad() { printf '  %s✗%s %s\n' "$YELLOW" "$RESET" "$1"; return 1; }

# die "msg" stops the wizard.
die() { printf '\n  %s✗ %s%s\n\n' "$YELLOW" "$1" "$RESET" >&2; exit 1; }

# missing_rpms PKG... prints the packages that are not installed.
missing_rpms() {
  local p
  for p in "$@"; do rpm -q "$p" >/dev/null 2>&1 || printf '%s\n' "$p"; done
}

# browse URL opens the browser, but only prints the URL in a dry run.
browse() { if (( DRY_RUN )); then note "dry-run: would open $1"; else open_url "$1"; fi; }

# pause_live "msg" waits for the human, but never in a dry run.
pause_live() { (( DRY_RUN )) || pause "$1"; }

stage_preflight() {
  stage "Preflight"
  say "This wizard sets up tethys for agent runs. Run it as $AGENT_USER."
  [[ "$(id -un)" == "$AGENT_USER" ]] || die "Run as $AGENT_USER (you are $(id -un))."
  ok "running as $AGENT_USER"
  [[ -r /etc/os-release ]] && . /etc/os-release
  [[ "${ID:-}" == "fedora" ]] || die "Only Fedora is supported (found '${ID:-unknown}')."
  ok "Fedora ${VERSION_ID:-?}"
  command -v sudo >/dev/null 2>&1 || die "sudo is not installed."
  if (( DRY_RUN )); then
    note "dry-run: would ask for your sudo password (sudo -v)"
  else
    say "Some stages need sudo. Enter your password if asked."
    sudo -v || die "sudo failed."
    ok "sudo works"
  fi
  pause_live "Press Enter to start."
}

stage_packages() {
  stage "System packages"
  say "tmux, jq, ShellCheck, unison, git, gh, curl and Playwright's browser libraries."
  local -a todo
  mapfile -t todo < <(missing_rpms "${TOOL_PACKAGES[@]}" "${PLAYWRIGHT_PACKAGES[@]}")
  if (( ${#todo[@]} )); then
    note "missing: ${todo[*]}"
    run sudo dnf -y install "${todo[@]}"
  else
    ok "all packages already installed"
  fi
  (( DRY_RUN )) && return 0
  local c
  for c in tmux jq shellcheck unison git gh curl; do
    command -v "$c" >/dev/null 2>&1 && ok "$c: $(command -v "$c")" || bad "$c is not on PATH"
  done
  say "Unison must be the same version on vidar and tethys:"
  note "tethys: $(unison -version 2>&1 | head -n1)"
  note "Compare with 'unison -version' on vidar."
}

stage_docker() {
  stage "Docker CE"
  say "Docker Engine from Docker's own Fedora repository, with compose and buildx."
  local -a docker_pkgs=(docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin)
  if [[ ! -f /etc/yum.repos.d/docker-ce.repo ]]; then
    run sudo dnf -y install dnf-plugins-core
    if dnf --version 2>/dev/null | grep -qi dnf5; then
      run sudo dnf config-manager addrepo --from-repofile="$DOCKER_REPO_URL"
    else
      run sudo dnf config-manager --add-repo "$DOCKER_REPO_URL"
    fi
  else
    ok "docker-ce repository already added"
  fi
  local -a todo
  mapfile -t todo < <(missing_rpms "${docker_pkgs[@]}")
  if (( ${#todo[@]} )); then
    note "missing: ${todo[*]}"
    run sudo dnf -y install "${docker_pkgs[@]}"
  else
    ok "Docker packages already installed"
  fi
  systemctl is-enabled docker >/dev/null 2>&1 && systemctl is-active docker >/dev/null 2>&1 \
    || run sudo systemctl enable --now docker
  id -nG "$AGENT_USER" | tr ' ' '\n' | grep -qx docker \
    || run sudo usermod -aG docker "$AGENT_USER"
  (( DRY_RUN )) && return 0
  systemctl is-active docker >/dev/null 2>&1 && ok "docker service is running" || bad "docker service is not running"
  id -nG "$AGENT_USER" | tr ' ' '\n' | grep -qx docker && ok "$AGENT_USER is in the docker group" || bad "$AGENT_USER is not in the docker group"
  if sudo docker compose version >/dev/null 2>&1; then
    ok "$(sudo docker compose version)"
  else
    bad "docker compose plugin missing"
  fi
  if ! docker info >/dev/null 2>&1; then
    warn "This shell does not have the docker group yet. Log out and back in (or run 'newgrp docker') before agent-user.sh."
  else
    ok "docker works without sudo"
  fi
}

stage_linger() {
  stage "Keep corvus's services running after logout"
  say "tmux sessions and systemd user services must survive SSH disconnects."
  if [[ "$(loginctl show-user "$AGENT_USER" -p Linger --value 2>/dev/null)" == "yes" ]]; then
    ok "linger already enabled"
  else
    run sudo loginctl enable-linger "$AGENT_USER"
  fi
  (( DRY_RUN )) && return 0
  [[ "$(loginctl show-user "$AGENT_USER" -p Linger --value 2>/dev/null)" == "yes" ]] \
    && ok "linger is enabled" || bad "linger is not enabled"
}

# op_ready: the 1Password CLI is installed (installs it from 1Password's rpm repo).
ensure_op_cli() {
  command -v op >/dev/null 2>&1 && { ok "op: $(op --version)"; return 0; }
  say "The 1Password CLI is missing; adding 1Password's rpm repository."
  if (( DRY_RUN )); then note "dry-run: would add /etc/yum.repos.d/1password.repo and install 1password-cli"; return 0; fi
  sudo rpm --import https://downloads.1password.com/linux/keys/1password.asc
  sudo tee /etc/yum.repos.d/1password.repo >/dev/null <<'REPO'
[1password]
name=1Password Stable Channel
baseurl=https://downloads.1password.com/linux/rpm/stable/$basearch
enabled=1
gpgcheck=1
repo_gpgcheck=1
gpgkey=https://downloads.1password.com/linux/keys/1password.asc
REPO
  sudo dnf -y install 1password-cli
  ok "op: $(op --version)"
}

# op_token_works: the stored token is a service account that reads the vault.
op_token_works() {
  [[ -s "$OP_TOKEN_FILE" ]] || return 1
  OP_SERVICE_ACCOUNT_TOKEN="$(cat "$OP_TOKEN_FILE")" op whoami >/dev/null 2>&1 || return 1
  OP_SERVICE_ACCOUNT_TOKEN="$(cat "$OP_TOKEN_FILE")" op vault get "$OP_VAULT" >/dev/null 2>&1
}

stage_op() {
  stage "1Password service account"
  ensure_op_cli
  run mkdir -p "$WW_CONFIG_DIR"
  run chmod 700 "$WW_CONFIG_DIR"
  if [[ -s "$OP_TOKEN_FILE" ]]; then
    [[ "$(stat -c %a "$OP_TOKEN_FILE")" == "600" ]] || run chmod 600 "$OP_TOKEN_FILE"
  fi
  if op_token_works; then
    ok "the token in $OP_TOKEN_FILE works and reads the '$OP_VAULT' vault"
    return 0
  fi
  say "Create a service account the agents use to read Development settings."
  browse "https://start.1password.com/developer-tools/infrastructure-secrets/serviceaccount/"
  step "Developer → Directory → Infrastructure Secrets → Service Accounts → Create a Service Account."
  step "Name it 'Watt Wise Development'."
  step "Grant access to the '$OP_VAULT' vault only, with Read permission only (no Write)."
  step "Create it and copy the token (starts ops_). It is shown once."
  note "Docs: https://developer.1password.com/docs/service-accounts/get-started/"
  if (( DRY_RUN )); then note "dry-run: would read the token (hidden) into $OP_TOKEN_FILE, mode 600"; return 0; fi
  local OP_TOKEN_INPUT=""
  ask_secret OP_TOKEN_INPUT "Paste the service account token:"
  [[ -n "$OP_TOKEN_INPUT" ]] || die "No token entered."
  (umask 077 && printf '%s' "$OP_TOKEN_INPUT" > "$OP_TOKEN_FILE")
  chmod 600 "$OP_TOKEN_FILE"
  unset OP_TOKEN_INPUT
  ok "wrote $OP_TOKEN_FILE (mode 600)"
  op_token_works || die "The token could not read the '$OP_VAULT' vault. Check the vault access and run again."
  ok "op whoami works and the vault is readable"
  local whoami_out
  whoami_out="$(OP_SERVICE_ACCOUNT_TOKEN="$(cat "$OP_TOKEN_FILE")" op whoami 2>&1 || true)"
  note "$(printf '%s' "$whoami_out" | head -n3)"
  warn "Check in 1Password that the account has Read-only access (the CLI can't prove that)."
}

stage_github() {
  stage "GitHub token"
  if env -u GH_TOKEN -u GITHUB_TOKEN gh api "repos/$GH_REPO" --jq .full_name >/dev/null 2>&1; then
    ok "gh is signed in and can read $GH_REPO"
    return 0
  fi
  say "Create a fine-grained token limited to this repository."
  browse "https://github.com/settings/personal-access-tokens/new"
  step "Token name: 'tethys agents'. Expiration: 90 days or less."
  step "Resource owner: $GH_USER. Repository access: Only select repositories → $GH_REPO."
  step "Repository permissions: Contents = Read and write, Pull requests = Read and write, Metadata = Read-only."
  step "Leave everything else unset: no Workflows, no Administration, no Secrets, no account permissions."
  step "Generate the token and copy it (starts github_pat_)."
  if (( DRY_RUN )); then note "dry-run: would read the token (hidden) and run: gh auth login --with-token"; return 0; fi
  local GH_TOKEN_INPUT=""
  ask_secret GH_TOKEN_INPUT "Paste the token:"
  [[ -n "$GH_TOKEN_INPUT" ]] || die "No token entered."
  printf '%s' "$GH_TOKEN_INPUT" | env -u GH_TOKEN -u GITHUB_TOKEN gh auth login --hostname github.com --with-token
  unset GH_TOKEN_INPUT
  env -u GH_TOKEN -u GITHUB_TOKEN gh api "repos/$GH_REPO" --jq .full_name >/dev/null 2>&1 \
    && ok "gh can read $GH_REPO" || die "gh cannot read $GH_REPO; check the token's repository access."
  # A token scoped to one repository must not see the maintainer's other repositories.
  local others
  others="$(env -u GH_TOKEN -u GITHUB_TOKEN gh api user/repos --paginate --jq '.[].full_name' 2>/dev/null | grep -vcx "$GH_REPO" || true)"
  if [[ "${others:-0}" -gt 0 ]]; then
    warn "The token can see $others other repositories. Recreate it with 'Only select repositories'."
  else
    ok "the token sees only $GH_REPO"
  fi
}

stage_signing() {
  stage "Commit signing"
  say "Agent commits on epic branches must be signed with an SSH key registered on GitHub as a signing key."
  local fmt gpgsign keyspec pub
  fmt="$(git config --global --get gpg.format || true)"
  gpgsign="$(git config --global --get commit.gpgsign || true)"
  keyspec="$(git config --global --get user.signingkey || true)"
  [[ "$fmt" == "ssh" ]] && ok "gpg.format = ssh" || bad "gpg.format is '${fmt:-unset}'" || true
  [[ "$gpgsign" == "true" ]] && ok "commit.gpgsign = true" || bad "commit.gpgsign is '${gpgsign:-unset}'" || true
  [[ -n "$keyspec" ]] && ok "user.signingkey = $keyspec" || bad "user.signingkey is unset" || true
  if [[ "$fmt" != "ssh" || "$gpgsign" != "true" || -z "$keyspec" ]]; then
    if (( DRY_RUN )); then
      note "dry-run: would offer to set gpg.format, commit.gpgsign and user.signingkey"
      return 0
    fi
    if [[ -z "$keyspec" ]]; then
      local keys
      keys="$(ls "$HOME"/.ssh/*.pub 2>/dev/null || true)"
      [[ -n "$keys" ]] && note "public keys here: $keys"
      say "No signing key set. Create one if needed:  ssh-keygen -t ed25519 -f ~/.ssh/tethys_signing -C 'tethys signing'"
      ask keyspec "Path of the public key to sign with:"
    fi
    confirm "Set gpg.format=ssh, commit.gpgsign=true and user.signingkey=$keyspec (global)?" \
      || die "Signing is required. Set the three git settings and run again."
    git config --global gpg.format ssh
    git config --global commit.gpgsign true
    git config --global user.signingkey "$keyspec"
  fi
  # The key may be a path to the private key or the public key, or 'key::ssh-ed25519 ...'.
  pub="${keyspec#key::}"
  if [[ "$keyspec" == key::* ]]; then
    pub="$(printf '%s' "$pub" | awk '{print $1" "$2}')"
  else
    pub="${pub/#\~/$HOME}"
    [[ "$pub" == *.pub ]] || pub="$pub.pub"
    [[ -r "$pub" ]] || die "Public key $pub not found."
    pub="$(awk '{print $1" "$2}' "$pub")"
  fi
  (( DRY_RUN )) && { note "dry-run: would compare $pub with GitHub's signing keys"; return 0; }
  ok "key: ${pub:0:40}..."
  local registered
  # The scoped token has no account permissions, so user/ssh_signing_keys usually
  # fails; the public endpoint lists the same keys.
  registered="$(env -u GH_TOKEN -u GITHUB_TOKEN gh api user/ssh_signing_keys --jq '.[].key' 2>/dev/null || true)"
  [[ -n "$registered" ]] || registered="$(curl -fsS "https://api.github.com/users/$GH_USER/ssh_signing_keys" | jq -r '.[].key')"
  if printf '%s\n' "$registered" | awk '{print $1" "$2}' | grep -qxF "$pub"; then
    ok "the key is registered on GitHub as a signing key"
    return 0
  fi
  warn "This key is not registered as a signing key on $GH_USER's account."
  say "A plain authentication key does not count. Add it as a signing key:"
  browse "https://github.com/settings/ssh/new"
  step "Title: 'tethys signing'. Key type: Signing Key (not Authentication Key)."
  step "Paste the public key:"
  printf '  %s\n' "$pub"
  pause "Press Enter once it is added."
  registered="$(curl -fsS "https://api.github.com/users/$GH_USER/ssh_signing_keys" | jq -r '.[].key')"
  printf '%s\n' "$registered" | awk '{print $1" "$2}' | grep -qxF "$pub" \
    && ok "the key is registered as a signing key" \
    || die "GitHub does not list the key as a signing key yet."
}

run_wizard() {

ENV_FILE=/dev/null  # this wizard writes no .env values
TOTAL_STAGES=7
local arg
for arg in "$@"; do
  case "$arg" in
    --dry-run) DRY_RUN=1 ;;
    -h|--help) sed -n '/^# Usage:/,/^#   --dry-run/p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) die "Unknown option: $arg" ;;
  esac
done

banner "Watt-Wise agent host: tethys setup"

stage_preflight
stage_packages
